INSERT INTO project_tidy_jobs (
    user_id, course_id, generation, status, base_tree_version, previous_proposal_id,
    input_snapshot_json, max_attempts, next_run_at
) VALUES (
    #{userId}, #{courseId}, #{generation}, #{status}, #{baseTreeVersion}, #{previousProposalId},
    #{inputSnapshotJson}, #{maxAttempts}, #{nextRunAt}
)

mapper.select:
SELECT * FROM project_tidy_jobs
 WHERE course_id = #{courseId} AND user_id = #{userId}
 ORDER BY job_id DESC LIMIT 1

mapper.insert:
INSERT INTO project_tidy_proposals (
    user_id, course_id, job_id, generation, revision, base_tree_version, status,
    summary_json, ops_json, scope_json, previous_proposal_id, model
) VALUES (
    #{userId}, #{courseId}, #{jobId}, #{generation}, #{revision}, #{baseTreeVersion}, #{status},
    #{summaryJson}, #{opsJson}, #{scopeJson}, #{previousProposalId}, #{model}
)

mapper.select:
SELECT * FROM project_tidy_proposals
 WHERE course_id = #{courseId} AND user_id = #{userId}
 ORDER BY proposal_id DESC
 LIMIT #{limit}

mapper.update:
UPDATE project_tidy_proposals
   SET status = #{status},
       applied_result_json = COALESCE(#{appliedResultJson}, applied_result_json),
       superseded_by_proposal_id = COALESCE(#{supersededByProposalId}, superseded_by_proposal_id),
       resolved_at = #{resolvedAt}
 WHERE proposal_id = #{proposalId} AND user_id = #{userId}

UPDATE project_tidy_proposals
   SET status = #{status}, applied_result_json = #{appliedResultJson}, resolved_at = #{resolvedAt}
 WHERE proposal_id = #{proposalId} AND user_id = #{userId}
   AND status = 'PROPOSED' AND revision = #{expectedRevision}

