INSERT INTO project_tidy_proposal_materials (
    proposal_id, user_id, material_id, file_hash, analysis_version, section_count, reviewed_count,
    included, exclude_reason
) VALUES (
    #{proposalId}, #{userId}, #{materialId}, #{fileHash}, #{analysisVersion}, #{sectionCount},
    #{reviewedCount}, #{included}, #{excludeReason}
)

mapper.select:
SELECT * FROM project_tidy_proposal_materials
 WHERE proposal_id = #{proposalId} AND user_id = #{userId}
 ORDER BY included DESC, id ASC

mapper.update:
UPDATE project_tidy_edits
   SET edits_json = #{editsJson}, edit_revision = edit_revision + 1
 WHERE proposal_id = #{proposalId} AND user_id = #{userId} AND edit_revision = #{expectedRevision}
